//! A206 (MANDATE-v4 §12 / §33) — the WSID_V1 canonical layout, pinned.
//!
//! The golden digests below were computed OUTSIDE the code under test, with
//! python3 hashlib over the documented canonical layout, and cross-checked by
//! a second independent byte assembly (§32: expected hashes are never
//! generated by the code being tested). If the implementation ever disagrees
//! with them, the layout moved — that is a versioned migration to WSID_V2,
//! never a test update. Real-repository behavior lives in the workspace
//! oracle (`a206_workspace_oracle.rs`); this file is the layout contract and
//! the structural read-only gate.

use thruline_core::ledger::Ledger;
use thruline_core::observation::{verify_chain, AppendOutcome, ReceiptTerminal};
use thruline_core::workspace_identity::{
    canonical_bytes, digest_of, identity_of, record_observation, ConflictEntry, DirtyEntry,
    Observation, RecordOutcome, RenamedEntry, Scope, StagedEntry, SubmoduleEntry, SymlinkEntry,
    UntrackedEntry, WorkspaceDoc,
};

fn clean_doc() -> WorkspaceDoc {
    WorkspaceDoc {
        scope: Scope {
            include_untracked: true,
            exclusions: vec![],
        },
        repo_id: Some("1".repeat(64)),
        root: "/w/repo".to_string(),
        git_common_dir: "/w/repo/.git".to_string(),
        worktree_id: Some("2".repeat(64)),
        branch: Some("main".to_string()),
        head: Some("3".repeat(40)),
        index_digest: "4".repeat(64),
        staged: vec![],
        dirty: vec![],
        deleted: vec![],
        renamed: vec![],
        conflicts: vec![],
        untracked: vec![],
        symlinks: vec![],
        submodules: vec![],
        sparse_digest: None,
        lfs_digest: None,
    }
}

/// Vector W1 — clean tree on a branch, minimal document.
#[test]
fn golden_vector_w1_minimal_document() {
    let doc = clean_doc();
    assert_eq!(
        canonical_bytes(&doc).len(),
        669,
        "hand-computed canonical length, vector W1"
    );
    assert_eq!(
        digest_of(&doc),
        "9b70c35edde8fab7e14751e05f5fab3e3e9423e413efbc716344a98457ee2eea"
    );
    assert_eq!(
        identity_of(&doc),
        "wsid1:9b70c35edde8fab7e14751e05f5fab3e3e9423e413efbc716344a98457ee2eea",
        "the stored identity string carries its own version tag"
    );
}

/// Vector W2 — every section populated: detached HEAD, declared exclusions,
/// one entry in each list, sparse and LFS digests present.
#[test]
fn golden_vector_w2_every_section_populated() {
    let doc = WorkspaceDoc {
        scope: Scope {
            include_untracked: true,
            exclusions: vec!["node_modules/".to_string(), "target/".to_string()],
        },
        repo_id: Some("a".repeat(64)),
        root: "/w/full".to_string(),
        git_common_dir: "/w/full/.git".to_string(),
        worktree_id: Some("b".repeat(64)),
        branch: None,
        head: Some("c".repeat(40)),
        index_digest: "d".repeat(64),
        staged: vec![StagedEntry {
            path: "src/new.rs".to_string(),
            head_mode: "000000".to_string(),
            index_mode: "100644".to_string(),
            index_object: "e".repeat(40),
        }],
        dirty: vec![DirtyEntry {
            path: "src/lib.rs".to_string(),
            worktree_mode: "100644".to_string(),
            worktree_sha256: "f".repeat(64),
        }],
        deleted: vec!["gone.txt".to_string()],
        renamed: vec![RenamedEntry {
            new_path: "new-name.txt".to_string(),
            old_path: "old-name.txt".to_string(),
            head_mode: "100644".to_string(),
            index_mode: "100644".to_string(),
            index_object: "0".repeat(40),
        }],
        conflicts: vec![ConflictEntry {
            path: "clash.txt".to_string(),
            modes: [
                "100644".to_string(),
                "100644".to_string(),
                "100644".to_string(),
            ],
            objects: ["1".repeat(40), "2".repeat(40), "3".repeat(40)],
        }],
        untracked: vec![UntrackedEntry {
            path: "notes.md".to_string(),
            sha256: "5".repeat(64),
        }],
        symlinks: vec![SymlinkEntry {
            path: "link".to_string(),
            target: "../elsewhere".to_string(),
        }],
        submodules: vec![SubmoduleEntry {
            path: "vendor/dep".to_string(),
            state: " ".to_string(),
            head: "6".repeat(40),
        }],
        sparse_digest: Some("7".repeat(64)),
        lfs_digest: Some("8".repeat(64)),
    };
    assert_eq!(
        canonical_bytes(&doc).len(),
        1565,
        "hand-computed canonical length, vector W2"
    );
    assert_eq!(
        digest_of(&doc),
        "2cdc1a96d8efd205472b411d9f1a76f0b2857bc8b0c9e3c71c8d80d318407b67"
    );
}

/// Vector W3 — unborn repository: repo identity abstains, no worktree id, no
/// HEAD, a branch symbolic ref, the empty index digest, one untracked file.
#[test]
fn golden_vector_w3_unborn_repository() {
    let doc = WorkspaceDoc {
        scope: Scope {
            include_untracked: true,
            exclusions: vec![],
        },
        repo_id: None,
        root: "/w/unborn".to_string(),
        git_common_dir: "/w/unborn/.git".to_string(),
        worktree_id: None,
        branch: Some("main".to_string()),
        head: None,
        // sha256 of zero index entries = sha256 of the empty byte string.
        index_digest: "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
            .to_string(),
        staged: vec![],
        dirty: vec![],
        deleted: vec![],
        renamed: vec![],
        conflicts: vec![],
        untracked: vec![UntrackedEntry {
            path: "first.txt".to_string(),
            sha256: "9".repeat(64),
        }],
        symlinks: vec![],
        submodules: vec![],
        sparse_digest: None,
        lfs_digest: None,
    };
    assert_eq!(
        canonical_bytes(&doc).len(),
        570,
        "hand-computed canonical length, vector W3"
    );
    assert_eq!(
        digest_of(&doc),
        "1e8e8cc0bbb6b4d9fa3c518e5154a83d916ba5359b7e8843ab40bbb209c7ab0b"
    );
}

/// Every content field, changed alone, must move the digest — including the
/// option tags and the field boundaries the length prefixes exist for.
#[test]
fn distinct_documents_yield_distinct_digests() {
    let reference = digest_of(&clean_doc());
    let mut variants: Vec<String> = Vec::new();

    let mut d = clean_doc();
    d.scope.include_untracked = false;
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.scope.exclusions = vec!["x/".to_string()];
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.repo_id = None;
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.repo_id = Some(String::new());
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.root = "/w/repo2".to_string();
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.git_common_dir = "/w/repo/.git2".to_string();
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.worktree_id = None;
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.branch = None;
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.branch = Some(String::new());
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.head = None;
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.index_digest = "5".repeat(64);
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.deleted = vec!["a".to_string()];
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.untracked = vec![UntrackedEntry {
        path: "a".to_string(),
        sha256: String::new(),
    }];
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.sparse_digest = Some("s".repeat(64));
    variants.push(digest_of(&d));
    let mut d = clean_doc();
    d.lfs_digest = Some("l".repeat(64));
    variants.push(digest_of(&d));

    let mut all = variants.clone();
    all.push(reference.clone());
    for v in &variants {
        assert_ne!(v, &reference, "a changed field must change the digest");
    }
    let unique: std::collections::BTreeSet<_> = all.iter().collect();
    assert_eq!(unique.len(), all.len(), "no two variants may collide");
}

/// The regression the length-prefixed encoding exists for: content shifted
/// across a field boundary must never produce the same bytes.
#[test]
fn encoding_is_injective_across_field_boundaries() {
    // root/common boundary.
    let mut a = clean_doc();
    a.root = "/w/ab".to_string();
    a.git_common_dir = "c".to_string();
    let mut b = clean_doc();
    b.root = "/w/a".to_string();
    b.git_common_dir = "bc".to_string();
    assert_ne!(digest_of(&a), digest_of(&b));

    // Within one staged entry.
    let entry = |path: &str, mode: &str| {
        let mut d = clean_doc();
        d.staged = vec![StagedEntry {
            path: path.to_string(),
            head_mode: mode.to_string(),
            index_mode: "100644".to_string(),
            index_object: "e".repeat(40),
        }];
        digest_of(&d)
    };
    assert_ne!(entry("ab", "c00644"), entry("a", "bc00644"));

    // List-count boundary: two exclusions vs their concatenation.
    let mut two = clean_doc();
    two.scope.exclusions = vec!["a".to_string(), "b".to_string()];
    let mut one = clean_doc();
    one.scope.exclusions = vec!["ab".to_string()];
    assert_ne!(digest_of(&two), digest_of(&one));

    // The same path as a deletion vs as an untracked file with empty digest.
    let mut del = clean_doc();
    del.deleted = vec!["p".to_string()];
    let mut unt = clean_doc();
    unt.untracked = vec![UntrackedEntry {
        path: "p".to_string(),
        sha256: String::new(),
    }];
    assert_ne!(digest_of(&del), digest_of(&unt));
}

/// Law 1's teeth, extended from the snapshotter to the fingerprinter: no
/// mutating git verb, and no direct process spawn — every subprocess must go
/// through the guarded plumbing runner.
#[test]
fn the_fingerprinter_is_structurally_read_only() {
    let src = std::fs::read_to_string(
        std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("src/workspace_identity.rs"),
    )
    .expect("read module");
    for verb in [
        "\"commit\"",
        "\"stash\"",
        "\"reset\"",
        "\"checkout\"",
        "\"clean\"",
        "\"push\"",
        "\"pull\"",
        "\"merge\"",
        "\"rebase\"",
        "\"restore\"",
        "\"rm\"",
        "\"mv\"",
        "\"apply\"",
        "\"init\"",
        "\"add\"",
        "\"tag\"",
        "\"branch\"",
        "\"switch\"",
        "\"fetch\"",
        "\"clone\"",
        "\"gc\"",
        "\"update-ref\"",
        "\"update-index\"",
        "\"read-tree\"",
        "\"write-tree\"",
        "\"checkout-index\"",
        "\"filter-branch\"",
    ] {
        assert!(
            !src.contains(verb),
            "workspace_identity.rs invokes git {verb} — the fingerprinter reads, it never runs"
        );
    }
    assert!(
        !src.contains("Command::new"),
        "workspace_identity.rs spawns directly — subprocesses go through the guarded runner only"
    );
}

/// An incomplete observation records honestly: completeness `incomplete`,
/// NULL workspace identity (there is no digest to store), the reason inside
/// the receipt, and the receipt still terminating at filesystem state.
#[test]
fn an_incomplete_observation_is_recorded_without_an_identity() {
    let ledger = Ledger::open_in_memory().expect("ledger");
    let obs = Observation::Incomplete {
        reason: "the workspace changed during observation — capture again".to_string(),
        repo_id: Some("9".repeat(64)),
        root: "/w/moving".to_string(),
    };
    let out = record_observation(&ledger, &obs, "2026-08-31T12:00:00Z", "cli:test", None)
        .expect("record");
    let RecordOutcome::Recorded {
        outcome,
        workspace_identity,
    } = out
    else {
        panic!("a repo-identified incomplete observation must be recorded");
    };
    assert_eq!(workspace_identity, None, "no digest exists to store");
    let rec = outcome.record();
    assert_eq!(rec.observation_type_raw, "WORKSPACE_OBSERVED");
    assert_eq!(rec.completeness_raw, "incomplete");
    assert!(rec.workspace_identity.is_none());
    let receipt = rec.receipt().expect("receipt parses");
    assert_eq!(
        receipt.terminal,
        ReceiptTerminal::Filesystem {
            path: "/w/moving".to_string(),
            sha256: None,
        }
    );
    assert_eq!(
        receipt
            .extra
            .get("incomplete_reason")
            .and_then(|v| v.as_str()),
        Some("the workspace changed during observation — capture again")
    );
    assert_eq!(verify_chain(&ledger).expect("verify"), 1);

    // Idempotent by content identity, like every observation.
    let again = record_observation(&ledger, &obs, "2026-08-31T12:00:00Z", "cli:test", None)
        .expect("record again");
    let RecordOutcome::Recorded { outcome, .. } = again else {
        panic!("recorded");
    };
    assert!(matches!(*outcome, AppendOutcome::AlreadyRecorded(_)));
}

/// No repository identity means no observation — an abstention with a stated
/// reason, never a placeholder in a NOT NULL column.
#[test]
fn recording_abstains_without_a_repository_identity() {
    let ledger = Ledger::open_in_memory().expect("ledger");
    let obs = Observation::Incomplete {
        reason: "moving".to_string(),
        repo_id: None,
        root: "/w/anon".to_string(),
    };
    let out = record_observation(&ledger, &obs, "2026-08-31T12:00:00Z", "cli:test", None)
        .expect("record");
    let RecordOutcome::NoRepositoryIdentity { reason } = out else {
        panic!("must abstain, not invent a repository identity");
    };
    assert!(reason.contains("not recorded"), "the abstention says why");
    assert_eq!(verify_chain(&ledger).expect("verify"), 0, "nothing landed");
}
